<?php use Luna\Core\Csrf;use Luna\Core\View;$token=View::e(Csrf::token());?>
<div class="page-intro"><div><span class="eyebrow">Customer communication</span><h1>Comunicazioni e tracking</h1><p>Coda affidabile, retry automatico e tracciamento aperture/click rispettoso dei dati tecnici.</p></div><form method="post" action="/operations/communications/process"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button">Elabora coda ora</button></form></div>
<div class="two-columns"><section class="card form-card"><div class="card-header"><h2>Invio documento</h2></div><form method="post" action="/operations/communications/queue" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Documento<select name="document_id"><option value="">Nessuno</option><?php foreach($documents as $d):?><option value="<?= (int)$d['id'] ?>"><?= View::e($d['number'].' · '.$d['counterparty_name']) ?></option><?php endforeach;?></select></label><label class="field">Destinatario<input type="email" name="recipient" required></label><label class="field">Oggetto<input name="subject" required></label><label class="field full-width">Messaggio HTML<textarea name="html_body" rows="7" required></textarea></label><div class="form-actions full-width"><button class="button primary">Accoda invio</button></div></form></section>
<section class="card form-card"><div class="card-header"><div><h2>Trasporto e-mail</h2><p>Il campo segreto contiene solo un riferimento, es. ENV:LUNA_SMTP_PASSWORD.</p></div></div><form method="post" action="/operations/communications/settings" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Trasporto<select name="transport"><option <?= ($settings['transport']??'')==='DISABLED'?'selected':'' ?>>DISABLED</option><option <?= ($settings['transport']??'')==='SMTP'?'selected':'' ?>>SMTP</option><option <?= ($settings['transport']??'')==='SENDMAIL'?'selected':'' ?>>SENDMAIL</option></select></label><label class="field">Host<input name="host" value="<?= View::e($settings['host']??'') ?>"></label><label class="field">Porta<input type="number" name="port" value="<?= (int)($settings['port']??587) ?>"></label><label class="field">Cifratura<select name="encryption"><option>TLS</option><option>SMTPS</option><option>NONE</option></select></label><label class="field">Username<input name="username" value="<?= View::e($settings['username']??'') ?>"></label><label class="field">Riferimento segreto<input name="secret_reference" value="<?= View::e($settings['secret_reference']??'') ?>" placeholder="ENV:LUNA_SMTP_PASSWORD"></label><label class="field">Mittente<input type="email" name="from_email" value="<?= View::e($settings['from_email']??'') ?>"></label><label class="field">Nome mittente<input name="from_name" value="<?= View::e($settings['from_name']??'') ?>"></label><label class="field">Base tracking HTTPS<input type="url" name="tracking_base_url" value="<?= View::e($settings['tracking_base_url']??'') ?>"></label><label class="checkbox-field"><input type="checkbox" name="tracking_enabled" value="1" <?= !empty($settings['tracking_enabled'])?'checked':'' ?>><span>Tracking attivo</span></label><input type="hidden" name="max_attempts" value="5"><div class="form-actions full-width"><button class="button primary">Salva configurazione</button></div></form></section></div>
<section class="card"><div class="card-header"><h2>Storico invii</h2></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Documento</th><th>Destinatario</th><th>Oggetto</th><th>Stato</th><th>Tentativi</th><th>Aperture</th><th>Click</th><th>Errore</th></tr></thead><tbody><?php foreach($messages as $m):?><tr><td><?= View::date($m['created_at']) ?></td><td><?= View::e($m['document_number']??'—') ?></td><td><?= View::e($m['recipient']) ?></td><td class="primary-cell"><?= View::e($m['subject']) ?></td><td><span class="badge status-<?= strtolower($m['status']) ?>"><?= View::e($m['status']) ?></span></td><td><?= (int)$m['attempts'] ?></td><td><?= (int)$m['opens'] ?></td><td><?= (int)$m['clicks'] ?></td><td title="<?= View::e($m['error_message']??'') ?>"><?= View::e(mb_substr((string)($m['error_message']??''),0,60)) ?></td></tr><?php endforeach;?></tbody></table></div></section>
